/* teste do desafio repartir-figurinhas — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario faz a SUA captura: freopen para um arquivo proprio, chamada
   da funcao do aluno, fflush (nunca fclose no stdout) e leitura de volta. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void repartirFigurinhas(void);

SM_TEST(quanto_cada_um_leva) {
    freopen("sm_saida_1.tmp", "w", stdout);
    repartirFigurinhas();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a parte de cada amigo", linha, "cada um leva 9\n",
              "47 dividido por 5 entre inteiros da 9: o C corta a parte quebrada");
    fclose(f);
}

SM_TEST(quantas_foram_distribuidas) {
    freopen("sm_saida_2.tmp", "w", stdout);
    repartirFigurinhas();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    fgets(linha, 80, f);
    checa_str("o total distribuido", linha, "distribuidas: 45\n",
              "9 para cada um dos 5 amigos da 45, e nao os 47 do comeco");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda linha: nenhuma linha extra e aceita");
    fclose(f);
}

