#include <stdio.h>

void repartirFigurinhas(void) {
    int figurinhas = 47;
    int amigos = 5;

    int cada = figurinhas / amigos;
    printf("cada um leva %d\n", cada);
    printf("distribuidas: %d\n", cada * amigos);
}
